    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="title">Monster Battle</h1>
  <h2 id="meTx">You ❤️ 30</h2>
  <h2 id="monTx">Monster 👾 40</h2>
  <div id="btns" class="box row">
    <button id="atkBtn">Attack ⚔️</button>
  </div>
  <h2 id="result"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var hp, mhp;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function turn() {
      hp = (typeof hp === 'number' ? hp : 0) + -1 * mathRandomInt(2, 7);
      document.getElementById("meTx").textContent = 'You ❤️ ' + String(hp);
      document.getElementById("monTx").textContent = 'Monster 👾 ' + String(mhp);
      if (mhp <= 0) {
        document.getElementById("result").textContent = 'You defeated the monster! 🏆';
        __show("btns", "hide");
      } else if (hp <= 0) {
        document.getElementById("result").textContent = 'You fainted... 💀';
        __show("btns", "hide");
      }
