  <button id="ok">확인</button>
  <h3 id="msg"></h3>
  <script>
    var secret;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("ok").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("g").value) || 0) == secret) {
        document.getElementById("msg").textContent = '정답! 🎉';
      } else if ((parseFloat(document.getElementById("g").value) || 0) > secret) {
        document.getElementById("msg").textContent = '너무 커요';
      } else {
        document.getElementById("msg").textContent = '너무 작아요';
      }
    });

    secret = mathRandomInt(1, 100);
  </script>
</body>
