    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fff8e1; color: #1f2937; text-align: center; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h2 id="title1">아래 문장을 똑같이 쳐 보세요</h2>
  <h3 id="goal">오늘도 즐거운 코딩 시간</h3>
  <input id="typing" type="text" placeholder="여기에 입력">
  <h1 id="time">0</h1>
  <h3 id="msg"></h3>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];

    var t, on;

    document.getElementById("typing").addEventListener('input', function () {
      on = true;
      if (document.getElementById("typing").value == document.getElementById("goal").textContent) {
        __timers.forEach(clearInterval);
        document.getElementById("msg").textContent = ['완성! 걸린 시간: ',t / 10,'초'].join('');
      }
    });
    __timers.push(setInterval(function () {
      if (on) {
        t = (typeof t === 'number' ? t : 0) + 1;
        document.getElementById("time").textContent = t / 10;
        if (t >= 200) {
          __timers.forEach(clearInterval);
          document.getElementById("msg").textContent = '시간 초과!';
          __show("typing", "hide");
        }
      }
    }, 100));

    t = 0;
    on = false;
  </script>
</body>
</html>
