  <script>
    var g, streak, flip, best;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    // 이 함수를 설명하세요...
    function guess(g) {
      flip = listsGetRandomItem(['Heads', 'Tails'], false);
      if (g == flip) {
        streak = (typeof streak === 'number' ? streak : 0) + 1;
        if (streak > best) {
          best = streak;
        }
        document.getElementById("res").textContent = String(flip) + ' - correct! ✅';
      } else {
        streak = 0;
        document.getElementById("res").textContent = String(flip) + ' - wrong ❌';
      }
      document.getElementById("st").textContent = ['Streak: ',streak,' · Best: ',best].join('');
    }

    document.getElementById("hd").addEventListener('click', function () {
      guess('Heads');
    });
    document.getElementById("tl").addEventListener('click', function () {
      guess('Tails');
    });

    streak = 0;
    best = 0;
  </script>
</body>
