  <script>
    var acts, r, a;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("next").addEventListener('click', function () {
      r = (typeof r === 'number' ? r : 0) + 1;
      document.getElementById("round").textContent = 'Round ' + String(r);
      a = listsGetRandomItem(acts, false);
      if (mathRandomInt(1, 2) == 1) {
        document.getElementById("cmd").textContent = ['Simon says: ',a,'!'].join('');
      } else {
        document.getElementById("cmd").textContent = String(a) + '!';
      }
    });

    acts = ['jump', 'clap', 'spin', 'sit down'];
    r = 0;
  </script>
</body>
