  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'기린'의 영어 단어는?","a":"giraffe","o":["tiger","horse","giraffe"]},{"q":"'오리'의 영어 단어는?","a":"duck","o":["duck","tiger","giraffe"]},{"q":"'돼지'의 영어 단어는?","a":"pig","o":["monkey","bear","pig"]},{"q":"'사자'의 영어 단어는?","a":"lion","o":["bear","lion","monkey"]},{"q":"'코끼리'의 영어 단어는?","a":"elephant","o":["horse","elephant","pig"]},{"q":"'호랑이'의 영어 단어는?","a":"tiger","o":["elephant","tiger","dog"]},{"q":"'토끼'의 영어 단어는?","a":"rabbit","o":["bear","rabbit","tiger"]},{"q":"'원숭이'의 영어 단어는?","a":"monkey","o":["rabbit","monkey","pig"]},{"q":"'고양이'의 영어 단어는?","a":"cat","o":["tiger","cat","lion"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
