    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h2 id="t">1부터 N까지 계산</h2>
  <input id="n" type="number" placeholder="N (1~200)">
  <button id="go">계산</button>
  <p id="a"></p>
  <p id="b"></p>
  <p id="c"></p>
  <script>
    var limit, total, evens, primes, i;

    function mathIsPrime(n) {
      // https://en.wikipedia.org/wiki/Primality_test#Naive_methods
      if (n == 2 || n == 3) {
        return true;
      }
      // False if n is NaN, negative, is 1, or not whole.
      // And false if n is divisible by 2 or 3.
      if (isNaN(n) || n <= 1 || n % 1 !== 0 || n % 2 === 0 || n % 3 === 0) {
        return false;
      }
      // Check all the numbers of form 6k +/- 1, up to sqrt(n).
      for (var x = 6; x <= Math.sqrt(n) + 1; x += 6) {
        if (n % (x - 1) === 0 || n % (x + 1) === 0) {
          return false;
        }
      }
      return true;
    }

    document.getElementById("go").addEventListener('click', function () {
      limit = Math.min(Math.max((parseFloat(document.getElementById("n").value) || 0), 1), 200);
      total = 0;
      evens = 0;
      primes = 0;
      var i_inc = 1;
      if (1 > limit) {
        i_inc = -i_inc;
      }
      for (i = 1; i_inc >= 0 ? i <= limit : i >= limit; i += i_inc) {
        total = (typeof total === 'number' ? total : 0) + i;
        if (i % 2 === 0) {
          evens = (typeof evens === 'number' ? evens : 0) + i;
        }
        if (mathIsPrime(i)) {
          primes = (typeof primes === 'number' ? primes : 0) + 1;
        }
      }
      document.getElementById("a").textContent = ['1부터 ',limit,'까지 합: ',total].join('');
      document.getElementById("b").textContent = '짝수만 더하면: ' + String(evens);
      document.getElementById("c").textContent = '소수 개수: ' + String(primes);
    });
  </script>
</body>
</html>
