      pen = "#22c55e";
    });
    document.getElementById("blackBtn").addEventListener('click', function () {
      pen = "#111111";
    });
    document.getElementById("bigBtn").addEventListener('click', function () {
      r = 12;
    });
    document.getElementById("smallBtn").addEventListener('click', function () {
      r = 4;
    });

