    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="title">📝 To-do list</h1>
  <p id="hint">Write a task and press Add. When done, press Finish!</p>
  <div id="inputRow" class="box row">
    <input id="todoBox" type="text" placeholder="e.g. Homework">
    <button id="Add">➕ Add</button>
  </div>
  <div id="buttonRow" class="box row">
    <button id="finish">✔ Finish the top task</button>
    <button id="clearAll">🗑 Clear all</button>
  </div>
  <p id="Alerts"></p>
  <h3 id="todoTitle">📌 To do</h3>
  <ul id="todoList"></ul>
  <h3 id="doneTitle">✅ Done</h3>
  <ul id="doneList"></ul>
  <p id="count"></p>
  <script>
    function $(name) {
      if (name && name.nodeType) return name;
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" element does not exist');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }
    var __audio, __sndBus = null;
    function __snd() {
      if (!__audio) {
        __audio = new (window.AudioContext || window.webkitAudioContext)();
        ['pointerdown', 'keydown'].forEach(function (k) { document.addEventListener(k, function () { if (__audio.state === 'suspended') __audio.resume(); }); });
      }
      if (__audio.state === 'suspended') __audio.resume();
      if (!__sndBus) { __sndBus = __audio.createGain(); __sndBus.connect(__audio.destination); }
      return __sndBus;
    }
    function __tone(freq, t, sec, type, vol, to, hold) {
      var o = __audio.createOscillator(), g = __audio.createGain();
      o.type = type;
      o.frequency.setValueAtTime(freq, t);
      if (to) o.frequency.exponentialRampToValueAtTime(to, t + sec);
      g.gain.setValueAtTime(vol, t);
      if (hold) g.gain.setValueAtTime(vol, t + sec * hold);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.connect(g); g.connect(__snd());
      o.start(t); o.stop(t + sec + 0.02);
    }
    function __sfx(k) {
      __snd();
      var t = __audio.currentTime;
      if (k === 'coin') { __tone(988, t, 0.08, 'square', 0.1); __tone(1319, t + 0.08, 0.3, 'square', 0.1); }
      else if (k === 'jump') __tone(260, t, 0.25, 'square', 0.1, 820);
      else if (k === 'laser') __tone(1500, t, 0.22, 'sawtooth', 0.08, 120);
      else if (k === 'pop') __tone(500, t, 0.09, 'sine', 0.3, 1100);
      else if (k === 'win') [523.25, 659.25, 783.99, 1046.5].forEach(function (f, i) { __tone(f, t + i * 0.1, 0.3, 'triangle', 0.22); });
      else if (k === 'lose') [392, 349.23, 311.13, 261.63].forEach(function (f, i) { __tone(f, t + i * 0.18, 0.3, 'sawtooth', 0.08, 0, 0.6); });
      else if (k === 'boom') {
        var n = __audio.createBuffer(1, Math.round(__audio.sampleRate * 0.6), __audio.sampleRate), d = n.getChannelData(0);
        for (var i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 2);
        var s = __audio.createBufferSource(), f = __audio.createBiquadFilter();
        s.buffer = n; f.type = 'lowpass'; f.frequency.value = 900;
        s.connect(f); f.connect(__snd());
        s.start(t);
      }
    }

    var todos, item, doneItems;

    // Redraw both lists on the page
    function show_lists() {
      document.getElementById("todoList").textContent = '';
      for (var item_index in todos) {
        item = todos[item_index];
        __add("todoList", item);
      }
      document.getElementById("doneList").textContent = '';
      for (var item_index2 in doneItems) {
        item = doneItems[item_index2];
        __add("doneList", item);
      }
      document.getElementById("count").textContent = ['Left: ',todos.length,' · Done: ',doneItems.length,''].join('');
    }

    function add() {
      // Put the text at the end of the to-do list
      if (!document.getElementById("todoBox").value.length) {
        document.getElementById("Alerts").textContent = '✋ Write a task first';
      } else {
        todos.push(document.getElementById("todoBox").value);
        document.getElementById("todoBox").value = '';
        document.getElementById("Alerts").textContent = '';
        __sfx("pop");
        show_lists();
      }
    }

    document.getElementById("Add").addEventListener('click', function () {
      add();
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        add();
      }
    });
    document.getElementById("finish").addEventListener('click', function () {
      // Take the top task and move it to done
      if (!todos.length) {
        document.getElementById("Alerts").textContent = '🙌 Nothing left to do';
      } else {
        doneItems.push(todos.shift());
        document.getElementById("Alerts").textContent = '👍 Well done!';
        __sfx("coin");
        show_lists();
      }
    });
    document.getElementById("clearAll").addEventListener('click', function () {
      todos = [];
      doneItems = [];
      document.getElementById("Alerts").textContent = 'All cleared';
      show_lists();
    });

    // Start with two empty lists
    todos = [];
    doneItems = [];
    show_lists();
  </script>
</body>
</html>
