    const questions = [{"q":"'일요일'의 영어 단어는?","a":"Sunday","o":["Wednesday","Saturday","Sunday"]},{"q":"'월요일'의 영어 단어는?","a":"Monday","o":["Tuesday","Monday","Wednesday"]},{"q":"'화요일'의 영어 단어는?","a":"Tuesday","o":["Tuesday","Thursday","Friday"]},{"q":"'수요일'의 영어 단어는?","a":"Wednesday","o":["Thursday","Wednesday","Saturday"]},{"q":"'토요일'의 영어 단어는?","a":"Saturday","o":["Saturday","Sunday","Friday"]},{"q":"'금요일'의 영어 단어는?","a":"Friday","o":["Wednesday","Thursday","Friday"]},{"q":"'목요일'의 영어 단어는?","a":"Thursday","o":["Sunday","Thursday","Monday"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
