<head>
  <meta charset="UTF-8">
  <title>튕기는 공</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #dcfce7; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    canvas { background: #ffffff; border: 3px solid #94a3b8; border-radius: 8px; }
  </style>
</head>
<body>
  <h1>튕기는 공</h1>
  <canvas id="canvas" width="480" height="320"></canvas>
  <p>화면을 누르면 공이 늘어나요</p>
  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const balls = [];

    function addBall() {
      balls.push({
        x: Math.random() * (canvas.width - 52) + 26,
        y: Math.random() * (canvas.height - 52) + 26,
        dx: (Math.random() < 0.5 ? -1 : 1) * 4,
        dy: (Math.random() < 0.5 ? -1 : 1) * 4
      });
    }

    for (let i = 0; i < 5; i++) {
      addBall();
    }

    canvas.addEventListener('click', function () {
      addBall();
    });

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      balls.forEach(function (b) {
        b.x += b.dx;
        b.y += b.dy;
        if (b.x < 26 || b.x > canvas.width - 26) b.dx = -b.dx;
        if (b.y < 26 || b.y > canvas.height - 26) b.dy = -b.dy;
        ctx.beginPath();
        ctx.arc(b.x, b.y, 26, 0, Math.PI * 2);
        ctx.fillStyle = '#f97316';
        ctx.fill();
      });
      requestAnimationFrame(draw);
    }

    draw();
  </script>
</body>
</html>
