<body>
  <h1 id="title">Einkaufsrechner 🧾</h1>
  <input id="preis" type="number" placeholder="Preis (€)">
  <input id="menge" type="number" placeholder="Menge">
  <button id="add">Hinzufügen</button>
  <ul id="posten"></ul>
  <h2 id="summe">Summe: 0 €</h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var total, p;

    document.getElementById("add").addEventListener('click', function () {
      p = (parseFloat(document.getElementById("preis").value) || 0) * (parseFloat(document.getElementById("menge").value) || 0);
      total = (typeof total === 'number' ? total : 0) + p;
      __add("posten", [(parseFloat(document.getElementById("menge").value) || 0),' × ',(parseFloat(document.getElementById("preis").value) || 0),' € = ',p,' €'].join(''));
      document.getElementById("summe").textContent = ['Summe: ',total,' €'].join('');
    });

    total = 0;
  </script>
</body>
</html>
