  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var qn, score, ans;

    document.getElementById("제출").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("답칸").value) || 0) == ans) {
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("알림말").textContent = '맞았어요! 👍';
        document.getElementById("알림말").style.color = "#22c55e";
        __beep(523.25, 0.15);
      } else {
        document.getElementById("알림말").textContent = '아쉬워요. 정답은 ' + String(ans);
        document.getElementById("알림말").style.color = "#ef4444";
        __beep(261.63, 0.2);
      }
      document.getElementById("점수판").textContent = '점수: ' + String(score);
      qn = (typeof qn === 'number' ? qn : 0) + 1;
      document.getElementById("답칸").value = '';
      if (qn == 2) {
        document.getElementById("문제").textContent = '9 x 6 = ?';
        ans = 54;
      } else if (qn == 3) {
        document.getElementById("문제").textContent = '100 / 4 = ?';
        ans = 25;
      } else {
        document.getElementById("문제").textContent = ['끝! 점수는 ',score,' / 3'].join('');
        __show("제출", "hide");
        __show("답칸", "hide");
      }
    });

    qn = 1;
    score = 0;
    ans = 7;
  </script>
</body>
