<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>좋아하는 과목 투표</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #ede9fe; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    .row { margin: 8px 0; }
    .bar { display: inline-block; height: 18px; background: #3b82f6; border-radius: 4px; vertical-align: middle; margin: 0 8px; width: 0; }
  </style>
</head>
<body>
  <h1>좋아하는 과목 투표</h1>
  <div id="options"></div>
  <p id="total"></p>
  <script>
    const options = ["과학","국어","수학","체육","음악","영어","미술"];
    const votes = {};
    const box = document.getElementById('options');
    const totalEl = document.getElementById('total');

    function total() {
      let sum = 0;
      options.forEach(function (name) { sum += votes[name]; });
      return sum;
    }

    function update() {
      const sum = total();
      options.forEach(function (name) {
        const percent = sum ? Math.round(votes[name] / sum * 100) : 0;
        document.getElementById('bar-' + options.indexOf(name)).style.width = percent * 2 + 'px';
        document.getElementById('num-' + options.indexOf(name)).textContent = votes[name] + '표 (' + percent + '%)';
      });
      totalEl.textContent = '모두 ' + sum + '표';
    }

    options.forEach(function (name, i) {
      votes[name] = 0;
      const row = document.createElement('div');
      row.className = 'row';
      const btn = document.createElement('button');
      btn.textContent = name;
      btn.addEventListener('click', function () {
        votes[name] += 1;
        update();
      });
      const bar = document.createElement('span');
      bar.id = 'bar-' + i;
      bar.className = 'bar';
      const num = document.createElement('span');
      num.id = 'num-' + i;
      row.appendChild(btn);
      row.appendChild(bar);
      row.appendChild(num);
      box.appendChild(row);
    });

    update();
  </script>
</body>
</html>
