<body>
  <h1>영어 과일 퀴즈</h1>
  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'체리'의 영어 단어는?","a":"cherry","o":["cherry","apple","tangerine","grape"]},{"q":"'수박'의 영어 단어는?","a":"watermelon","o":["watermelon","apple","tangerine","grape"]},{"q":"'배'의 영어 단어는?","a":"pear","o":["pear","cherry","banana","tangerine"]},{"q":"'바나나'의 영어 단어는?","a":"banana","o":["cherry","tangerine","lemon","banana"]},{"q":"'딸기'의 영어 단어는?","a":"strawberry","o":["grape","cherry","strawberry","banana"]},{"q":"'레몬'의 영어 단어는?","a":"lemon","o":["pear","tangerine","grape","lemon"]},{"q":"'귤'의 영어 단어는?","a":"tangerine","o":["cherry","tangerine","peach","pear"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
