    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">Reaction Test</h2>
  <div id="pad" class="box" style="background:#9ca3af">
    <h1 id="sign">⏸</h1>
  </div>
  <div id="btns" class="box row">
    <button id="go">Start</button>
    <button id="tap">Tap</button>
  </div>
  <p id="msg"></p>
  <p id="bestText">Best: -</p>
  <script>
    var __timers = [];

    var state, t, best;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      state = 1;
      document.getElementById("msg").textContent = 'Wait... press when it turns green!';
      document.getElementById("pad").style.background = "#ef4444";
      setTimeout(function () {
        if (state == 1) {
          state = 2;
          t = 0;
          document.getElementById("pad").style.background = "#22c55e";
          document.getElementById("sign").textContent = 'NOW!';
        }
      }, (mathRandomInt(2, 5)) * 1000);
    });
    document.getElementById("tap").addEventListener('click', function () {
      if (state == 1) {
        state = 0;
        document.getElementById("msg").textContent = 'Too soon! Start again';
        document.getElementById("pad").style.background = "#9ca3af";
      } else if (state == 2) {
        state = 0;
        document.getElementById("pad").style.background = "#9ca3af";
        document.getElementById("sign").textContent = '⏸';
        document.getElementById("msg").textContent = ['Reaction time: ',t,' s'].join('');
        if (best == 0 || t < best) {
          best = t;
          document.getElementById("bestText").textContent = ['Best: ',best,' s'].join('');
        }
      }
    });
    __timers.push(setInterval(function () {
      if (state == 2) {
        t = Math.round((t + 0.1) * 10) / 10;
      }
    }, 100));

    state = 0;
    t = 0;
    best = 0;
  </script>
</body>
</html>
