  <style>
    body { font-family: sans-serif; text-align: center; background: #fff8e1; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    .team { display: inline-block; background: #ffffff; border-radius: 12px; padding: 12px 24px; margin: 8px; }
    .total { font-size: 48px; font-weight: bold; margin: 8px 0; }
  </style>
</head>
<body>
  <h1>점수판</h1>
  <div id="board"></div>
  <button id="reset">모두 0점으로</button>
  <script>
    const teams = ["B팀","4반"];
    const steps = [1,2];
    const scores = {};
    const board = document.getElementById('board');

    teams.forEach(function (name) {
      scores[name] = 0;
      const box = document.createElement('div');
      box.className = 'team';
      const label = document.createElement('h2');
      const total = document.createElement('p');
      total.className = 'total';
      label.textContent = name;
      total.textContent = '0';
      box.appendChild(label);
      box.appendChild(total);
      steps.forEach(function (step) {
        const btn = document.createElement('button');
        btn.textContent = '+' + step;
        btn.addEventListener('click', function () {
          scores[name] += step;
          total.textContent = scores[name];
        });
        box.appendChild(btn);
      });
      board.appendChild(box);
    });

    document.getElementById('reset').addEventListener('click', function () {
      teams.forEach(function (name) { scores[name] = 0; });
      document.querySelectorAll('.total').forEach(function (el) { el.textContent = '0'; });
    });
  </script>
</body>
</html>
