    const questions = [{"q":"'할머니'의 영어 단어는?","a":"grandmother","o":["mom","grandfather","grandmother"]},{"q":"'동생'의 영어 단어는?","a":"younger sibling","o":["older sister","grandmother","younger sibling"]},{"q":"'할아버지'의 영어 단어는?","a":"grandfather","o":["older brother","dad","grandfather"]},{"q":"'엄마'의 영어 단어는?","a":"mom","o":["older brother","older sister","mom"]},{"q":"'누나'의 영어 단어는?","a":"older sister","o":["grandfather","older sister","grandmother"]},{"q":"'아빠'의 영어 단어는?","a":"dad","o":["dad","grandmother","younger sibling"]},{"q":"'형'의 영어 단어는?","a":"older brother","o":["dad","older brother","younger sibling"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
