      const bar = document.createElement('span');
      bar.id = 'bar-' + i;
      bar.className = 'bar';
      const num = document.createElement('span');
      num.id = 'num-' + i;
      row.appendChild(btn);
      row.appendChild(bar);
      row.appendChild(num);
      box.appendChild(row);
