    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🖱️ 마우스로 공 피하기</h1>
  <p>버틴 시간: <span id="time">0.0</span>초 · 목숨: <span id="lives">3</span></p>
  <canvas id="game" width="420" height="420"></canvas>
  <p id="msg">마우스로 파란 점을 움직여 빨간 공을 피하세요</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const msg = document.getElementById('msg');
    let player = { x: 210, y: 210, r: 10 };
    let balls = [];
    let score = 0;        // 버틴 시간 (0.02초 단위로 쌓여요)
    let lives = 3;
    let safeTime = 0;
    let running = false;
    let timer = null;

    function addBall() {
      // 플레이어와 멀리 떨어진 모서리에서 출발
      const x = player.x < W / 2 ? W - 20 : 20;
      const y = player.y < H / 2 ? H - 20 : 20;
      const angle = Math.random() * Math.PI * 2;
      balls.push({ x: x, y: y, r: 12, dx: Math.cos(angle) * 3, dy: Math.sin(angle) * 3 });
    }

    function updateInfo() {
      document.getElementById('time').textContent = (score / 50).toFixed(1);
      document.getElementById('lives').textContent = lives;
    }

    function startGame() {
      clearInterval(timer);
      player.x = 210; player.y = 210;
      balls = [];
      addBall();
      addBall();
      score = 0;
      lives = 3;
      safeTime = 50;
      running = true;
      msg.textContent = '';
      document.getElementById('start').textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! ' + (score / 50).toFixed(1) + '초 버텼어요';
    }

    function tick() {
      if (!running) return;
      score += 1;
      if (score % 250 === 0) addBall(); // 5초마다 공 하나 추가
      for (const b of balls) {
        b.x += b.dx;
        b.y += b.dy;
        if (b.x < b.r || b.x > W - b.r) b.dx = -b.dx;
        if (b.y < b.r || b.y > H - b.r) b.dy = -b.dy;
      }
      if (safeTime > 0) {
        safeTime -= 1;
      } else if (balls.some(function (b) { return Math.hypot(b.x - player.x, b.y - player.y) < b.r + player.r; })) {
        lives = Math.max(0, lives - 1);
        safeTime = 50;
        if (lives === 0) gameOver();
      }
      updateInfo();
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#ef4444';
      for (const b of balls) {
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
        ctx.fill();
      }
      if (safeTime % 10 < 5) {
        ctx.fillStyle = '#2563eb';
        ctx.beginPath();
        ctx.arc(player.x, player.y, player.r, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    canvas.addEventListener('mousemove', function (e) {
      if (!running) return;
      const rect = canvas.getBoundingClientRect();
      player.x = Math.max(player.r, Math.min(W - player.r, e.clientX - rect.left));
      player.y = Math.max(player.r, Math.min(H - player.r, e.clientY - rect.top));
    });
    document.getElementById('start').addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
