  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h1 id="title1">🎲 Roll 10 times</h1>
  <button id="rollBtn">Roll</button>
  <p id="rolls"></p>
  <h2 id="sixes"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var six, d;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("rollBtn").addEventListener('click', function () {
      six = 0;
      document.getElementById("rolls").textContent = '';
      for (var count = 0; count < 10; count++) {
        d = mathRandomInt(1, 6);
        __add("rolls", String(d) + ' ');
        if (d == 6) {
          six = (typeof six === 'number' ? six : 0) + 1;
        }
      }
      document.getElementById("sixes").textContent = 'Sixes: ' + String(six);
    });
  </script>
</body>
</html>
