  <h1>소풍 장소 투표</h1>
  <div id="options"></div>
  <p id="total"></p>
  <script>
    const options = ["놀이공원","공원","바다","동물원","박물관"];
    const votes = {};
    const box = document.getElementById('options');
    const totalEl = document.getElementById('total');

    function total() {
      let sum = 0;
      options.forEach(function (name) { sum += votes[name]; });
      return sum;
    }

    function update() {
      const sum = total();
      options.forEach(function (name) {
        const percent = sum ? Math.round(votes[name] / sum * 100) : 0;
        document.getElementById('bar-' + options.indexOf(name)).style.width = percent * 2 + 'px';
        document.getElementById('num-' + options.indexOf(name)).textContent = votes[name] + '표 (' + percent + '%)';
      });
      totalEl.textContent = '모두 ' + sum + '표';
    }

    options.forEach(function (name, i) {
      votes[name] = 0;
      const row = document.createElement('div');
      row.className = 'row';
      const btn = document.createElement('button');
      btn.textContent = name;
      btn.addEventListener('click', function () {
        votes[name] += 1;
        update();
      });
      const bar = document.createElement('span');
      bar.id = 'bar-' + i;
      bar.className = 'bar';
      const num = document.createElement('span');
      num.id = 'num-' + i;
      row.appendChild(btn);
      row.appendChild(bar);
      row.appendChild(num);
      box.appendChild(row);
    });

    update();
  </script>
</body>
</html>
