  <h3 id="res"></h3>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var answer, qs, as, score, i;

    // 이 함수를 설명하세요...
    function ask() {
      answer = as[(i - 1)];
      document.getElementById("q").textContent = qs[(i - 1)];
      document.getElementById("ans").value = '';
    }

    document.getElementById("checkBtn").addEventListener('click', function () {
      if (document.getElementById("ans").value.toLowerCase() == answer) {
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("res").textContent = '정답! 점수: ' + String(score);
      } else {
        document.getElementById("res").textContent = '땡! ❌';
      }
      i = (typeof i === 'number' ? i : 0) + 1;
      if (i > qs.length) {
        document.getElementById("q").textContent = ['퀴즈 끝! 점수: ',score,' / ',qs.length].join('');
        __show("row1", "hide");
      } else {
        ask();
      }
    });

    qs = ['사과', '바나나', '학교', '친구'];
    as = ['apple', 'banana', 'school', 'friend'];
    i = 1;
    score = 0;
    ask();
  </script>
