  <p id="tally">Heads: 0 · Tails: 0</p>
  <script>
    var heads, tails;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("flipBtn").addEventListener('click', function () {
      if (mathRandomInt(1, 2) == 1) {
        heads = (typeof heads === 'number' ? heads : 0) + 1;
        document.getElementById("coin").textContent = 'Heads';
      } else {
        tails = (typeof tails === 'number' ? tails : 0) + 1;
        document.getElementById("coin").textContent = 'Tails';
      }
      document.getElementById("tally").textContent = ['Heads: ',heads,' · Tails: ',tails].join('');
    });

    heads = 0;
    tails = 0;
  </script>
