    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var all;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("add").addEventListener('click', function () {
      if (!!document.getElementById("nameIn").value.length) {
        all.push(document.getElementById("nameIn").value);
        __add("names", document.getElementById("nameIn").value);
        document.getElementById("nameIn").value = '';
      }
    });
    document.getElementById("pick").addEventListener('click', function () {
      if (all.length > 0) {
        document.getElementById("winner").textContent = listsGetRandomItem(all, false);
        document.getElementById("winner").style.color = 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)';
      } else {
        document.getElementById("winner").textContent = 'Add some names first';
      }
    });

