  <ul id="out"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var i, row, j;

    document.getElementById("go").addEventListener('click', function () {
      document.getElementById("out").textContent = '';
      var i_end = Math.min(Math.max((parseFloat(document.getElementById("rows").value) || 0), 1), 10);
      var i_inc = 1;
      if (1 > i_end) {
        i_inc = -i_inc;
      }
      for (i = 1; i_inc >= 0 ? i <= i_end : i >= i_end; i += i_inc) {
        row = '';
        var j_inc = 1;
        if (1 > i) {
          j_inc = -j_inc;
        }
        for (j = 1; j_inc >= 0 ? j <= i : j >= i; j += j_inc) {
          row = String(row) + '⭐';
        }
        __add("out", row);
      }
    });
  </script>
</body>
</html>
