<body>
  <h1 id="title">Quiz de sumas</h1>
  <h1 id="qTx"></h1>
  <input id="ansIn" type="number" placeholder="Respuesta">
  <button id="checkBtn">Comprobar</button>
  <h2 id="result"></h2>
  <div id="sbox" class="box row">
    <p id="sLabel">Puntos</p>
    <h3 id="scoreTx">0</h3>
  </div>
  <script>
    var score, a, b;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newQ() {
      a = mathRandomInt(1, 20);
      b = mathRandomInt(1, 20);
      document.getElementById("qTx").textContent = [a,' + ',b,' = ?'].join('');
      document.getElementById("ansIn").value = '';
    }

    document.getElementById("checkBtn").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("ansIn").value) || 0) == a + b) {
        document.getElementById("result").textContent = '¡Correcto! ⭕';
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("scoreTx").textContent = score;
      } else {
        document.getElementById("result").textContent = '¡No! ❌';
      }
      newQ();
    });

    score = 0;
    newQ();
  </script>
</body>
</html>
