  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'바나나'의 영어 단어는?","a":"banana","o":["cherry","banana","strawberry","lemon"]},{"q":"'딸기'의 영어 단어는?","a":"strawberry","o":["strawberry","banana","peach","cherry"]},{"q":"'배'의 영어 단어는?","a":"pear","o":["peach","pear","lemon","strawberry"]},{"q":"'체리'의 영어 단어는?","a":"cherry","o":["strawberry","cherry","banana","watermelon"]},{"q":"'사과'의 영어 단어는?","a":"apple","o":["watermelon","banana","apple","strawberry"]},{"q":"'레몬'의 영어 단어는?","a":"lemon","o":["pear","tangerine","lemon","peach"]},{"q":"'수박'의 영어 단어는?","a":"watermelon","o":["peach","apple","pear","watermelon"]},{"q":"'귤'의 영어 단어는?","a":"tangerine","o":["lemon","pear","peach","tangerine"]},{"q":"'포도'의 영어 단어는?","a":"grape","o":["tangerine","grape","strawberry","lemon"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
