  <p id="num">굴리기를 눌러 보세요</p>
  <button id="roll">굴리기</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var faces, d;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("roll").addEventListener('click', function () {
      d = mathRandomInt(1, 6);
      document.getElementById("face").textContent = faces[(d - 1)];
      document.getElementById("num").textContent = String(d) + ' 나왔어요!';
    });

    faces = ['⚀', '⚁', '⚂', '⚃', '⚄', '⚅'];
    __size("face", "fontSize", 110);
  </script>
</body>
