  <p id="msg"></p>
  <script>
    const total = 180;
    let left = total;
    let timerId = null;
    const timeEl = document.getElementById('time');
    const msg = document.getElementById('msg');

    function stop() {
      clearInterval(timerId);
      timerId = null;
