  <h1 id="countText">0</h1>
  <script>
    var __timers = [];

    var clicks, ticks, state;

    document.getElementById("tapBtn").addEventListener('click', function () {
      if (state == 'ready') {
        state = 'run';
      }
      if (state == 'run') {
        clicks = (typeof clicks === 'number' ? clicks : 0) + 1;
        document.getElementById("countText").textContent = clicks;
      }
    });
    __timers.push(setInterval(function () {
      if (state == 'run') {
        ticks = (typeof ticks === 'number' ? ticks : 0) + -1;
        document.getElementById("timeText").textContent = ticks / 10;
        if (ticks <= 0) {
          state = 'done';
          document.getElementById("countText").textContent = String(clicks) + ' clicks!';
          document.getElementById("timeText").textContent = 'Time!';
        }
      }
    }, 100));

    clicks = 0;
    ticks = 100;
    state = 'ready';
  </script>
</body>
</html>
