        for (i = 1; i_inc >= 0 ? i <= i_end : i >= i_end; i += i_inc) {
          pool.push(i);
        }
        turn = 1;
        while (!!pool.length) {
          __add("res", [turn,'번째: ',listsGetRandomItem(pool, true),'번 사람'].join(''));
