    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var words, w, ok;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("say").addEventListener('click', function () {
      w = listsGetRandomItem(words, false);
      document.getElementById("word").textContent = w;
      __show("word", "show");
      document.getElementById("res").textContent = '';
      setTimeout(function () {
        __show("word", "hide");
      }, (2) * 1000);
    });
    document.getElementById("chk").addEventListener('click', function () {
      if (document.getElementById("ans").value.trim() == w) {
        ok = (typeof ok === 'number' ? ok : 0) + 1;
        document.getElementById("res").textContent = 'Correct! ✅';
