          scores[name] += step;
          total.textContent = scores[name];
        });
        box.appendChild(btn);
      });
      board.appendChild(box);
    });

    document.getElementById('reset').addEventListener('click', function () {
      teams.forEach(function (name) { scores[name] = 0; });
