  <ul id="histo"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var r;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("lancer").addEventListener('click', function () {
      r = mathRandomInt(1, 6);
      document.getElementById("de").textContent = r;
      __add("histo", 'Lancer : ' + String(r));
    });
    document.getElementById("effacer").addEventListener('click', function () {
      document.getElementById("histo").textContent = '';
    });
  </script>
</body>
