        document.getElementById("msg").textContent = '문이 열렸어요 🔓';
        document.getElementById("msg").style.color = "#22c55e";
      } else {
        wrong = (typeof wrong === 'number' ? wrong : 0) + 1;
        document.getElementById("msg").textContent = ['틀렸어요 (',wrong,'/3)'].join('');
        document.getElementById("msg").style.color = "#ef4444";
