    __timers.push(setInterval(function () {
      if (run) {
        t = (typeof t === 'number' ? t : 0) + -1;
        document.getElementById("left").textContent = t;
        if (t <= 0) {
          run = false;
          document.getElementById("msg").textContent = '시간 끝!';
          document.getElementById("msg").style.color = "#ef4444";
          __beep(440.00, 0.4);
          setTimeout(function () {
