  <h1 id="title">Catch the Dot</h1>
  <h2 id="score">Score: 0</h2>
  <canvas id="board" width="320" height="240"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __mx = 0, __my = 0;
    function __pos(e, el) {
      var r = el.getBoundingClientRect();
      __mx = Math.round((e.clientX - r.left) * (el.width ? el.width / r.width : 1));
      __my = Math.round((e.clientY - r.top) * (el.height ? el.height / r.height : 1));
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }

    var x, pts, y;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function drawDot() {
      x = mathRandomInt(20, 300);
      y = mathRandomInt(20, 220);
      __clear("board");
      __circle("board", x, y, 18, "#ef4444");
    }

    document.getElementById("board").addEventListener('click', function (e) {
      __pos(e, this);
      if (Math.abs(__mx - x) < 22 && Math.abs(__my - y) < 22) {
        pts = (typeof pts === 'number' ? pts : 0) + 1;
        document.getElementById("score").textContent = 'Score: ' + String(pts);
        __beep(329.63, 0.1);
        drawDot();
      }
    });

    pts = 0;
    drawDot();
  </script>
