<body>
  <h2 id="title">하이 로우</h2>
  <p id="q">다음 카드가 더 클까 작을까?</p>
  <h1 id="card">?</h1>
  <div id="btns" class="box row">
    <button id="hi">높다 ⬆️</button>
    <button id="lo">낮다 ⬇️</button>
  </div>
  <p id="msg"></p>
  <p id="streak">연속 정답: 0</p>
  <script>
    var cur, nx, s;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("hi").addEventListener('click', function () {
      nx = mathRandomInt(1, 13);
      if (nx > cur) {
        s = (typeof s === 'number' ? s : 0) + 1;
        document.getElementById("msg").textContent = '맞았어요!';
      } else {
        s = 0;
        document.getElementById("msg").textContent = '틀렸어요!';
      }
      cur = nx;
      document.getElementById("card").textContent = cur;
      document.getElementById("streak").textContent = '연속 정답: ' + String(s);
    });
    document.getElementById("lo").addEventListener('click', function () {
      nx = mathRandomInt(1, 13);
      if (nx < cur) {
        s = (typeof s === 'number' ? s : 0) + 1;
        document.getElementById("msg").textContent = '맞았어요!';
      } else {
        s = 0;
        document.getElementById("msg").textContent = '틀렸어요!';
      }
