  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var secret, g, d, tries, s, b, k, ch, r;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newGame() {
      secret = '';
      while (secret.length < 3) {
        d = mathRandomInt(0, 9);
        if (secret.indexOf('' + String(d)) + 1 == 0) {
          secret = String(secret) + String(d);
        }
      }
      tries = 0;
      document.getElementById("log").textContent = '';
      document.getElementById("msg").textContent = '';
    }

    document.getElementById("go").addEventListener('click', function () {
      g = document.getElementById("guess").value.trim();
      if (document.getElementById("guess").value.trim().length == 3) {
        s = 0;
        b = 0;
        for (k = 1; k <= 3; k++) {
          ch = g.charAt((k - 1));
          if (secret.charAt((k - 1)) == ch) {
            s = (typeof s === 'number' ? s : 0) + 1;
          } else if (secret.indexOf(ch) + 1 > 0) {
            b = (typeof b === 'number' ? b : 0) + 1;
          }
        }
        tries = (typeof tries === 'number' ? tries : 0) + 1;
        r = [s,'S ',b,'B'].join('');
        __add("log", [g,' → ',r].join(''));
        if (s == 3) {
          document.getElementById("msg").textContent = '🎉 정답! 시도: ' + String(tries);
        } else {
          document.getElementById("msg").textContent = r;
        }
        document.getElementById("guess").value = '';
      } else {
        document.getElementById("msg").textContent = '숫자 3개를 써 주세요';
      }
    });
    document.getElementById("newBtn").addEventListener('click', function () {
      newGame();
    });

    newGame();
  </script>
