    const questions = [{"q":"26 + 22 = ?","a":"48","o":["46","58","49","48"]},{"q":"14 + 47 = ?","a":"61","o":["58","61","60","51"]},{"q":"7 × 8 = ?","a":"56","o":["58","54","57","56"]},{"q":"54 - 34 = ?","a":"20","o":["21","20","22","25"]},{"q":"47 - 10 = ?","a":"37","o":["36","37","39","40"]},{"q":"57 - 25 = ?","a":"32","o":["37","32","35","22"]},{"q":"9 × 6 = ?","a":"54","o":["57","54","44","59"]},{"q":"29 + 32 = ?","a":"61","o":["59","51","61","63"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
