  <button id="next">다음</button>
  <script>
    const cards = [["포도","grape"],["레몬","lemon"],["귤","tangerine"],["바나나","banana"],["수박","watermelon"],["딸기","strawberry"]];
    let index = 0;
    let showBack = false;
    const cardEl = document.getElementById('card');
    const countEl = document.getElementById('count');

