  <p id="tally">Heads: 0 | Tails: 0</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var h, tl;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("flip").addEventListener('click', function () {
      if (mathRandomInt(1, 2) == 1) {
        h = (typeof h === 'number' ? h : 0) + 1;
        document.getElementById("side").textContent = 'Heads';
      } else {
        tl = (typeof tl === 'number' ? tl : 0) + 1;
        document.getElementById("side").textContent = 'Tails';
      }
      document.getElementById("tally").textContent = ['Heads: ',h,' | Tails: ',tl].join('');
    });

    h = 0;
    tl = 0;
    __size("coin", "fontSize", 72);
  </script>
</body>
</html>
